//! Icon pack registry: Lucide (default) + Tabler, Phosphor, Heroicons,
//! Feather, Material Symbols.
//!
//! Path data lives in `icons_data.rs` (generated by tools/gen_icons.py
//! from the upstream open-source packages — see that file's header for
//! sources + licenses). Every icon is normalized to absolute SVG path
//! commands on a 24x24 viewBox; Phosphor + Material Symbols are
//! fill-based (rendered with `fill`, no stroke), the other four packs
//! are stroke-based.
//!
//! A pack that lacks an equivalent for an icon falls back to Lucide for
//! that icon (recorded in icons_data.rs header). `path_for` never
//! returns an empty string for a known icon name.

mod icons_data;

/// (pack id, display name) — order = order in the Settings picker.
pub const PACKS: [(&str, &str); 6] = [
    ("lucide", "Lucide"),
    ("tabler", "Tabler"),
    ("phosphor", "Phosphor"),
    ("heroicons", "Heroicons"),
    ("feather", "Feather"),
    ("material", "Material Symbols"),
];

/// Packs rendered with `fill` instead of `stroke` (their upstream SVGs
/// are filled shapes, not stroked outlines).
pub fn is_fill_pack(pack: &str) -> bool {
    matches!(valid_icon_pack(pack).as_str(), "phosphor" | "material")
}

/// Validate an icon pack id — unknown value → "lucide" (same pattern as
/// `theme::valid_toggle_style`).
pub fn valid_icon_pack(raw: &str) -> String {
    let v = crate::theme::unquote(raw).to_lowercase();
    match v.as_str() {
        "tabler" | "phosphor" | "heroicons" | "feather" | "material" => v,
        _ => "lucide".to_string(),
    }
}

/// SVG path commands for an icon in a pack. Falls back to Lucide when
/// the pack has no equivalent; "" only for an unknown icon name.
pub fn path_for(pack: &str, name: &str) -> &'static str {
    let pack = valid_icon_pack(pack);
    if let Some(d) = icons_data::lookup(&pack, name) {
        return d;
    }
    if pack != "lucide" {
        if let Some(d) = icons_data::lookup("lucide", name) {
            return d;
        }
    }
    ""
}

/// All icon names the app uses (SvgIcon `name:` values across ui/*.slint,
//! incl. the radial-menu icon arrays). Used by tests to prove every
/// pack renders every icon.
pub const ALL_ICON_NAMES: [&str; 45] = [
    "arrow-left", "arrow-right", "bell", "book-open", "calendar", "check",
    "chevron-down", "copy", "crop", "download", "droplet", "edit-3",
    "external-link", "file-text", "folder", "folder-open", "grid",
    "hard-drive", "hash", "hexagon", "home", "image", "info", "layers",
    "lock", "maximize", "minimize", "more-horizontal", "palette", "plus",
    "puzzle", "refresh", "rotate-cw", "save", "search", "settings", "sun",
    "terminal", "trash", "user", "volume", "volume-x", "wrench", "x", "zap",
];

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn valid_icon_pack_accepts_known_and_defaults_unknown() {
        assert_eq!(valid_icon_pack("lucide"), "lucide");
        assert_eq!(valid_icon_pack("Tabler"), "tabler");
        assert_eq!(valid_icon_pack("PHOSPHOR"), "phosphor");
        assert_eq!(valid_icon_pack("\"heroicons\""), "heroicons");
        assert_eq!(valid_icon_pack("feather"), "feather");
        assert_eq!(valid_icon_pack("material"), "material");
        assert_eq!(valid_icon_pack(""), "lucide");
        assert_eq!(valid_icon_pack("nope"), "lucide");
    }

    #[test]
    fn is_fill_pack_only_phosphor_and_material() {
        assert!(is_fill_pack("phosphor"));
        assert!(is_fill_pack("material"));
        assert!(!is_fill_pack("lucide"));
        assert!(!is_fill_pack("tabler"));
        assert!(!is_fill_pack("heroicons"));
        assert!(!is_fill_pack("feather"));
    }

    #[test]
    fn every_pack_renders_every_icon() {
        for (pack, _) in PACKS {
            for name in ALL_ICON_NAMES {
                let d = path_for(pack, name);
                assert!(
                    !d.is_empty(),
                    "pack {pack} has no path for icon {name} (not even via Lucide fallback)"
                );
            }
        }
    }

    #[test]
    fn lucide_home_kept_verbatim() {
        // Regression guard: the default look must not change. This is the
        // exact path string from the old SvgIcon ternary in ui/design.slint.
        assert_eq!(
            path_for("lucide", "home"),
            "M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z M9 22V12h6v10"
        );
    }

    #[test]
    fn unknown_icon_is_empty_and_unknown_pack_falls_back_to_lucide() {
        assert_eq!(path_for("lucide", "does-not-exist"), "");
        assert_eq!(path_for("nope", "home"), path_for("lucide", "home"));
        // heroicons has no hexagon -> Lucide fallback, not empty.
        assert_eq!(path_for("heroicons", "hexagon"), path_for("lucide", "hexagon"));
    }
}
